package zw.ac.msu.dzimbahub.controller;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import zw.ac.msu.dzimbahub.auth.*; import zw.ac.msu.dzimbahub.model.Property; import zw.ac.msu.dzimbahub.repository.PropertyRepository; import java.util.*;
@RestController @RequestMapping("/api/landlord/properties") public class LandlordController {private final PropertyRepository properties;private final AppUserRepository users;public LandlordController(PropertyRepository p,AppUserRepository u){properties=p;users=u;} public record ListingRequest(@NotBlank String title,@NotBlank String area,@NotBlank String city,String address,String description,@Positive double price,String roomType,int bedrooms,int bathrooms,boolean furnished,double latitude,double longitude,String imageUrl,String amenitiesCsv){} private AppUser owner(Authentication a){AppUser u=users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));if(u.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Landlord access required.");return u;} private Property apply(Property p,ListingRequest r,AppUser u){p.setTitle(r.title());p.setArea(r.area());p.setCity(r.city());p.setAddress(r.address());p.setDescription(r.description());p.setPrice(r.price());p.setRoomType(r.roomType());p.setBedrooms(r.bedrooms());p.setBathrooms(r.bathrooms());p.setFurnished(r.furnished());p.setLatitude(r.latitude());p.setLongitude(r.longitude());p.setImageUrl(r.imageUrl());p.setAmenitiesCsv(r.amenitiesCsv());p.setLandlordId(u.getId());p.setLandlordName(u.getFullName());return p;}
 @GetMapping public List<Property> mine(Authentication a){AppUser u=owner(a);return properties.findAll().stream().filter(p->Objects.equals(p.getLandlordId(),u.getId())).toList();}
 @PostMapping public ResponseEntity<Property> create(@Valid @RequestBody ListingRequest r,Authentication a){AppUser u=owner(a);return ResponseEntity.status(HttpStatus.CREATED).body(properties.save(apply(new Property(),r,u)));}
 @PutMapping("/{id}") public Property update(@PathVariable Long id,@Valid @RequestBody ListingRequest r,Authentication a){AppUser u=owner(a);Property p=properties.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(p.getLandlordId(),u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return properties.save(apply(p,r,u));}
 @DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Long id,Authentication a){AppUser u=owner(a);Property p=properties.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(p.getLandlordId(),u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);properties.delete(p);return Map.of("message","Your listing has been removed.");}}
